<script setup lang="ts">import { ref } from "vue"; import { ElMessage,ElMessageBox } from "element-plus"; import { calculatePayroll,approvePayroll,payPayroll } from "../../api/hr"; const period=ref("");const payrollId=ref("");async function calculate(){try{const r=await calculatePayroll(period.value);payrollId.value=r.data?.data?.id??"";ElMessage.success("薪资已计算")}catch{ElMessage.error("薪资计算失败")}}async function pay(){try{await ElMessageBox.confirm("确认支付薪资？","确认");await approvePayroll(payrollId.value);await payPayroll(payrollId.value);ElMessage.success("薪资已支付")}catch(error){if(error!=="cancel")ElMessage.error("薪资支付失败")}}</script>
<template><el-card><template #header>薪资</template><el-input v-model="period" placeholder="YYYY-MM"/><el-button @click="calculate">计算</el-button><el-button @click="pay">审批并支付</el-button></el-card></template>
